import { Component, Element, Host, Prop, h } from "@stencil/core";

let id = 0;

/**
 * @since 2.0
 * @status experimental
 *
 * @slot - The tab panel's content.
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-tab-panel",
	styleUrl: "tab-panel.scss",
	shadow: true,
})
export class TabPanel {
	componentId = `tab-panel-${++id}`;

	@Element() host: HTMLHbrTabPanelElement;

	/** The tab panel's name. */
	@Prop({ reflect: true, mutable: true }) name = "";

	/** 'aria-label' attribute when a label is not set. */
	@Prop() arialabel: string;

	@Prop() ariarole: boolean | string = "tabpanel";

	/** When true, the tab panel will be shown. */
	@Prop({ reflect: true }) active = false;

	render() {
		let ariaProps = {};
		if (this.ariarole) {
			ariaProps = {
				role: this.ariarole,
				ariaHidden: this.active ? "false" : "true",
				ariaLabel: this.arialabel,
			};
		}
		return (
			// If the user didn't provide an ID, we'll set one so we can link tabs and tab panels with aria labels
			<Host
				id={this.host.id || this.componentId}
				style={{ display: this.active ? "block" : "none" }}
			>
				<div part="base" class="tab-panel" {...ariaProps}>
					<slot />
				</div>
			</Host>
		);
	}
}
